{
  "case_id": "xsu_sg_014_occupational_injury_opinion",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "not_met", "reason": "Svaret fejlfortolker udtalelsen som en vurdering af erhvervsskade og varig formindskning af arbejdsevnen. Det hævder, at Udbetaling Danmark er bundet af udtalelsen, hvis den er afgivet efter en 'saglig og mønstret vurdering'. Det er stik imod kilden, hvorefter udtalelsen er vejledende og ikke bindende. Det er en væsentlig juridisk fejl, som rubrikken udtrykkeligt nævner."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Svaret nævner ikke, hvor meget funktionsnedsættelsen påvirker evnen til at arbejde, eller om funktionsevnen er så nedsat, at et studiejob ikke kan varetages. Det nævner i stedet erhvervsrelateret skade og varig formindskning af arbejdsevnen."},
    "c03_direct_relevance": {"label": "not_met", "reason": "Svaret besvarer ikke korrekt nogen af spørgsmålets to dele: hvad udtalelsen skal belyse, og om Udbetaling Danmark er bundet. Indholdet er forkert og handler om erhvervsskade."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret henviser ikke til nogen identificerbar kilde, hverken lov, bekendtgørelse eller vejledning."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "not_met", "reason": "Svaret tilføjer en uunderbygget regel om, at Udbetaling Danmark er bundet af en 'saglig og mønstret' AES-udtalelse. Det tilføjer også betingelser om erhvervsskade og varig formindskning af arbejdsevnen samt en pligt til selv at vurdere, som kilderne ikke støtter."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Den krævede kvalifikation, at udtalelsen er vejledende og ikke bindende, mangler. Svaret hævder det modsatte som udgangspunkt."},
    "c09_reasoning_coherence": {"label": "not_met", "reason": "Svaret siger først, at Udbetaling Danmark er bundet, og derefter at styrelsen kan foretage en selvstændig vurdering ved tvivl. Det er ikke sammenhængende, og det udgår fra en forkert præmis om erhvervsskade."},
    "c10_legal_modality_precision": {"label": "not_met", "reason": "Svaret gør en ikke-bindende, vejledende udtalelse til noget bindende ('skal tage ... til følge'). Kildens 'er ikke bindende' bliver dermed til en pligt."}
  },
  "xhaile_coverage": {
    "A68": {"label": "no", "reason": "Svaret dækker ikke de to centrale vurderingspunkter: påvirkning af evnen til at arbejde og om et studiejob kan varetages. Det nævner heller ikke, at udtalelsen er vejledende, at den bygger på sagens dokumentation uden undersøgelse, eller at styrelsen betaler udgifterne. Det erstatter punkterne med erhvervsskade og varig formindskelse af arbejdsevnen."}
  },
  "overall_notes": "Svaret er juridisk forkert på centrale punkter. Det hævder, at Udbetaling Danmark er bundet af udtalelsen, hvilket er en væsentlig fejl ifølge rubrikken. Det angiver heller ikke nogen kilde. Derfor er C04 not_met, mens C05 og C06 er not_assessable."
}

